command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$main="74550ff2c67633371d1c3ad2e266c32a7e7c8ed1";$candidate="58cf87e95f55a640411593850c433e1daedb4c9a";$branch="work/unc-network-metadata-sort-20261007"
Set-Location -LiteralPath $repo
& git fetch origin main $branch --no-tags --prune
if($LASTEXITCODE -ne 0){throw "network metadata FAST2 fetch failed"}
if((& git rev-parse refs/remotes/origin/main).Trim() -ne $main){throw "main moved before network metadata FAST2"}
if((& git rev-parse ("refs/remotes/origin/"+$branch)).Trim() -ne $candidate){throw "network metadata FAST2 candidate moved"}
$temp=Join-Path $env:RUNNER_TEMP ("fly-network-metadata-fast2-"+$env:GITHUB_RUN_ID)
if(Test-Path -LiteralPath $temp){Remove-Item -LiteralPath $temp -Recurse -Force}
try{
 & git worktree add --detach $temp $candidate
 if($LASTEXITCODE -ne 0){throw "network metadata FAST2 worktree add failed"}
 Set-Location -LiteralPath $temp
 & git diff --check ($main+"..."+$candidate)
 if($LASTEXITCODE -ne 0){throw "network metadata FAST2 diff check failed"}
 & python -X utf8 tools\winui\run_checks.py fast --before $main --head $candidate
 if($LASTEXITCODE -ne 0){throw "network metadata FAST2 failed"}
 Write-Host "NETWORK_METADATA_FAST2=PASS"
 Write-Host "NETWORK_METADATA_DIFF_CHECK=PASS"
}finally{
 Set-Location -LiteralPath $repo
 if(Test-Path -LiteralPath $temp){& git worktree remove --force $temp}
 & git worktree prune
}
